class Learner():
    def __init__(self, args, input_dim, output_dim, scenario_train, scenario_test, deterministic = True): 
        if args.optimizer == "adam":
            self.optim_obj = optim.Adam
        elif args.optimizer == "ada_delta":
            self.optim_obj= optim.Adadelta
        else:
            self.optim_obj= optim.SGD

        if deterministic:
            torch.manual_seed(args.seed)
            random.seed(args.seed)
            np.random.seed(args.seed)
            torch.use_deterministic_algorithms(True)
            torch.backends.cudnn.benchmark = False

        self.input_dim = input_dim
        self.output_dim = output_dim
        if args.model == 'conv':
            self.model = ConvNet(input_dim, output_dim).to(DEVICE)
        else:
            self.model = MLP(input_dim, output_dim).to(DEVICE)
        print("Model: \n", self.model)
        self.args = args
        self.scenario_train = scenario_train
        self.scenario_test = scenario_test
        self.pruned_model = random_prune(self.model, args.prune_perc)

        self.freeze_masks = None
        self.freeze_masks_old = None
        self.drop_masks = None
        self.stable_indices = None
        self.num_dropped_connections = 0
        self.classes_so_far = []
        self.stable_units_set = []

        if self.args.p_step_size == 'cosine':
            self.p_schedule = lambda t: cosine_anneling(t, self.args.step_size_param)
        elif self.args.p_step_size == 'exp_decay':
            self.p_schedule = lambda t: exp_decay(t, self.args.step_size_param)
        else: 
            self.p_schedule = lambda t: linear(t, self.args.step_size_param)

    #task_id should start from 0
    #taskset is object of continuum library 
    def task_train(self, task_id, taskset, val_set = None):
        current_classes = list(taskset.get_classes())
        self.classes_so_far += current_classes
        print("Task ID: ", task_id + 1, " Classes: ", current_classes)
        #Create data loaders
        if val_set is None:
            train_taskset, val_taskset = split_train_val(taskset, val_split=0.1)
            train_loader = DataLoader(taskset2GPUdataset(train_taskset),  batch_size= self.args.batch_size,  shuffle=True)
            val_loader = DataLoader(taskset2GPUdataset(val_taskset),  batch_size= self.args.batch_size,  shuffle=True)
        else:
            train_loader = DataLoader(taskset2GPUdataset(taskset),  batch_size= self.args.batch_size,  shuffle=True)
            val_loader = DataLoader(taskset2GPUdataset(val_set),  batch_size= self.args.batch_size,  shuffle=True)

        test_set = self.scenario_test[task_id]  
        test_loader = DataLoader(taskset2GPUdataset(test_set), batch_size = self.args.batch_size*2, shuffle=False)

        #Get training objects
        loss = nn.CrossEntropyLoss()

        #Iterative FineTuning Step
        previous_model = None
        current_model = self.pruned_model
        stable_units_set =  self.stable_units_set
        stable_indices = self.stable_indices
        stable_indices_prev = None
        p_prev = 100
        p_new = 100
        acc_prev = 0
        connectivity_before = copy.deepcopy(get_masks(self.pruned_model))
        print('Starting:')
        t = 0
        list_of_ps = []
        num_stable_units = []

        while(True):
            t = t + 1
            stable_perc = self.p_schedule(t) * 100
            print('Model sparsity before training:', compute_weight_sparsity(current_model))
            #Reset optimizer for every task
            optimizer = self.optim_obj(current_model.parameters(), lr= self.args.learning_rate, weight_decay= 0)
            connectivity_before = copy.deepcopy(get_masks(current_model))

            current_model, _, _, acc_after_fine_tuning = training_CL(current_model, loss, optimizer, train_loader,
                val_loader, self.args, self.args.phase_epochs,
                current_classes, freeze_masks = self.freeze_masks, 
                multihead = bool(self.args.multihead))

            acc_new = acc_after_fine_tuning[-1]
            #Accuracy Dropped stop iteration
            if (acc_new < (acc_prev - self.args.recovery_perc) and t > 2) or stable_perc <= 5:
                self.pruned_model = previous_model
                if len(self.stable_units_set) == 0:
                    self.stable_units_set = [set(stable_index) for stable_index in stable_indices_prev]
                    self.stable_indices =  [list(stable_set) for stable_set in self.stable_units_set]
                else:
                    self.stable_units_set = [prev_set.union(set(stable_index)) for stable_index, prev_set in zip(stable_indices_prev, self.stable_units_set)]
                    self.stable_indices =  [list(stable_set) for stable_set in self.stable_units_set]
                self.freeze_masks, _ = compute_freeze_and_drop(self.stable_indices, self.pruned_model)
                if  self.args.reinit:
                    self.pruned_model.re_initialize(self.freeze_masks)
                break
            else:
                acc_prev = max(acc_new, acc_prev)
                previous_model = current_model
                stable_indices_prev = stable_indices
                p_prev = p_new
                num_stable_units.append(stable_indices_prev)
                list_of_ps.append(p_prev)

            print('Dropping for p:{}:'.format(stable_perc))
            current_model, _, num_dropped_connections, stable_indices, stable_units_set = compute_stable_and_drop_connections(
                                                                               current_model,  self.input_dim, self.stable_units_set, 
                                                                               train_loader, current_classes, 
                                                                               self.classes_so_far, stable_perc,  model_type= self.args.model )

            if  self.args.grow:
                #Grow connections
                connectivity_after = copy.deepcopy(get_masks(current_model))
                num_dropped_connections =  [torch.sum(torch.abs(a  - b)).cpu().numpy() for a, b in zip(connectivity_before, connectivity_after)]
                plastic_units = compute_plastic(current_model, stable_indices)
                #Fix Non importants without outgoing connections
                current_model, remainder_connections = fix_no_outgoing(current_model, plastic_units, num_dropped_connections)
                weights = list_of_weights(current_model)


                activations, _ = compute_average_activation(current_model, train_loader, DEVICE, current_classes, False)
                current_model, remainder_connections = grow_connection_A2B(current_model, remainder_connections,
                                                       [weights[0][0].shape[1]]  + [w.shape[0] for w, _ in weights], 
                                                       stable_indices,  activations, 
                                                       grow_algo = self.args.rewire_algo, 
                                                       weight_init_algo = self.args.grow_init)

                #Alternative growth
                current_model, remainder_connections = grow_connection_A2B(current_model, remainder_connections,
                                                       [weights[0][0].shape[1]]  + [w.shape[0] for w, _ in weights], 
                                                       stable_indices,  activations, 
                                                       grow_algo = 'full_random', 
                                                       weight_init_algo = self.args.grow_init)

            p_new = stable_perc
        print('End:')


        _, acc_after_drop, _ = test(self.pruned_model, loss, 
                                 test_loader,
                                 current_classes = current_classes if self.args.multihead else None)

        percentange_of_frozen_conns = connection_freeze_perc(self.freeze_masks, self.args.prune_perc)

        task_summary_log(self.pruned_model, loss, acc_after_drop, 
                                current_classes, self.args, 
                                task_id, self.scenario_test, self.stable_units_set)

        return p_prev, percentange_of_frozen_conns, acc_after_drop, 0, list_of_ps[1:], num_stable_units[1:]
import copy
import torch
import torch.nn as nn
from .config import DEVICE


def reset_frozen_gradients(network, freeze_masks):
    mask_index = 0
    for module in network.modules():
        if isinstance(module, nn.Linear) or  isinstance(module, nn.Conv2d):
            module.weight.grad[freeze_masks[mask_index][0]] = 0
            module.bias.grad[freeze_masks[mask_index][1]] = 0
            mask_index += 1
    return network



#Accepts number of epochs as a parameter
def training_CL(network, loss, optimizer, train_loader, test_loader,  args, epochs,
                    current_classes = None, freeze_masks = None, multihead = False): 
    #Early Stopping
    test_acc1_min = 0
    best_epoch = 0
    best_network = network
    if freeze_masks is not None:
        freeze_masks = [(torch.tensor(w).to(torch.bool).to(DEVICE) , torch.tensor(b).to(torch.bool).to(DEVICE)) for w, b in freeze_masks]
    #Training
    train_curve = []
    accuracy1 = []
    test_loss = []
    for epoch in range(epochs):
        network.train()
        train_loss = 0
        for batch_idx, (data, target) in enumerate(train_loader):
            optimizer.zero_grad()
            output = network(data, current_classes)
            batch_loss = loss(output, target.long())
            train_loss += batch_loss.item() * data.size(0)
            batch_loss.backward()
            if freeze_masks is not None:
                network = reset_frozen_gradients(network, freeze_masks)
            optimizer.step()

        train_curve.append(train_loss/len(train_loader.dataset))
        avg_loss, acc1, _ = test(network, loss, test_loader, current_classes = current_classes if multihead else None, report=True)
        accuracy1.append(acc1)
        test_loss.append(avg_loss)

        if acc1 > test_acc1_min:
            best_network = copy.deepcopy(network)
            best_epoch = epoch
            test_acc1_min = acc1

    return best_network, train_curve[:best_epoch+1], test_loss[:best_epoch+1], accuracy1[:best_epoch+1]

def test(network, loss, dataloader,  title = "test", current_classes = None, report = False):
    network.eval()
    total = 0
    correct1 = 0
    correct5 = 0
    with torch.no_grad():
        for idx, (data, target) in enumerate(dataloader):
            output = network(data, current_classes)
            total += loss(output, target.long()).item() * data.size(0)
            _, pred = output.topk(5, dim=1)
            correct = pred.eq(target.view(-1,1).expand_as(pred))
            correct1 += correct[:,:1].sum().item()
            correct5 += correct[:,:5].sum().item()
    avg_loss = total / len(dataloader.dataset)
    acc1 = 100.0 * correct1 / len(dataloader.dataset)
    acc5 = 100.0 * correct5 / len(dataloader.dataset)

    if report:
        print('[{}] Top 1 Accuracy ='.format(title), acc1)
        print('[{}] Top 5 Accuracy ='.format(title), acc5)
        print('[{}] Average Loss ='.format(title), avg_loss)

    return avg_loss, acc1, acc5
import numpy as np
import torch
from torch import nn
import copy
import math
from .config import DEVICE

#Place all dataset to GPU
def taskset2GPUdataset(task_set):
    try:
        task_set.get_sample(0)
    except:
        if task_set.nb_classes == 33 or task_set.nb_classes == 30:
            return torch.utils.data.TensorDataset(torch.tensor(task_set.get_raw_samples()[0]).to(DEVICE),
                                                  torch.tensor(task_set.get_raw_samples()[1]).to(DEVICE))
    x = []
    y = []
    for (data, target, _) in task_set:
        x.append(data)
        y.append(target)

    return torch.utils.data.TensorDataset(torch.stack(x).to(DEVICE), torch.tensor(y).to(DEVICE))


def cosine_anneling(t, k):
    return 0.5 * (1 + math.cos(t * math.pi / k))
def linear(t, k):
    return 1 - k*t
def exp_decay(t, k):
    return (t + 1)**(-k)

# Given stable units, find the plastic units
def compute_plastic(model, stable_indices):
    weight = list_of_weights(model)
    units = [w[1].shape[0] for w in weight]
    plastic_indices = []
    for i,  b_layer in enumerate(stable_indices[1:]):
        all_units = set(range(units[i]))
        plastic_units = all_units.difference(set(b_layer))
        plastic_indices.append(list(plastic_units))
    return [[]] + plastic_indices

#Get sparse connecivity masks
def  get_masks(model):
    l = []
    for module in model.modules():
        if isinstance(module, torch.nn.Linear) or isinstance(module, torch.nn.Conv2d) :
            weight_mask, _ = module.get_mask()
            l.append(weight_mask)
    return l

#Find stable untis and drop connections
def compute_stable_and_drop_connections(pruned_model, in_channels, stable_units_set, train_loader, current_classes, classes_so_far, stable_activation_perc, model_type):
    stable_units_set = copy.deepcopy(stable_units_set)
    pruned_model = copy.deepcopy(pruned_model)
    activation_before_drop, _ = compute_average_activation(pruned_model, train_loader,
                                                            DEVICE, current_classes, False)

    stable_indices_new = compute_stable_neurons(activation_before_drop,  in_channels, classes_so_far, activation_perc = stable_activation_perc, model_type = model_type)

    if len(stable_units_set) == 0:
        stable_units_set = [set(stable_index) for stable_index in stable_indices_new]
        stable_indices =  [list(stable_set) for stable_set in stable_units_set]
    else:
        stable_units_set = [prev_set.union(set(stable_index)) for stable_index, prev_set in zip(stable_indices_new, stable_units_set)]
        stable_indices =  [list(stable_set) for stable_set in stable_units_set]


    stable_indices_new = fix_dead_stable_units(stable_indices_new, pruned_model)

    freeze_masks_new, drop_masks = compute_freeze_and_drop(stable_indices, pruned_model)
    pruned_model, num_dropped_connections  = drop_connections(pruned_model, drop_masks, DEVICE)

    return pruned_model, freeze_masks_new, num_dropped_connections, stable_indices, stable_units_set

#Find the percentage of frozen connections
def connection_freeze_perc(freeze_masks, prune_perc):
    layers = []
    for freeze_mask in freeze_masks:
        a = freeze_mask[0].shape
        total_connections = int(np.prod(a)*(1 - prune_perc / 100))
        frozen_connections =  np.sum(freeze_mask[0])
        layers.append(100*(frozen_connections / total_connections))
    return layers


#Fix dead plastic units
def fix_no_outgoing(model, plastic_indices, num_dropped_connections):
    weight = []
    for module in model.modules():
        if isinstance(module, torch.nn.Linear) or isinstance(module, torch.nn.Conv2d):
            weight_mask, bias_mask = module.get_mask()
            weight.append((copy.deepcopy(weight_mask).cpu().numpy(), copy.deepcopy(bias_mask).cpu().numpy()))

    new_masks = [weight[0][0]]
    bias_masks = [weight[0][1]]
    for i, layer_indices in enumerate(plastic_indices[1:-1], start = 1):
        M = weight[i][0]
        kernel_size = (M.shape[2] * M.shape[3]) if len(M.shape) == 4 else 1
        for unit_index in layer_indices:
            #not enough connections to fix all
            if num_dropped_connections[i] == 0 or len(plastic_indices[i + 1]) == 0:
                continue
            #Dead unit
            if np.sum(np.abs(M[:, unit_index])) == 0:
                target = np.random.choice(plastic_indices[i + 1], 1)
                M[target, unit_index] = np.ones((M.shape[2], M.shape[3])) if len(M.shape) == 4 else 1
                num_dropped_connections[i] =  num_dropped_connections[i] - kernel_size
        new_masks.append(M)
        bias_masks.append(weight[i][1])
    new_masks.append(weight[-1][0])
    bias_masks.append(weight[-1][1])
    model.set_masks(new_masks, bias_masks)
    return model, num_dropped_connections


#Degrade dead stable units to plastic
def fix_dead_stable_units(stable_indices,  model):
    weight = []
    for module in model.modules():
        if isinstance(module, torch.nn.Linear) or isinstance(module, torch.nn.Conv2d):
            weight_mask, bias_mask = module.get_mask()
            weight.append((copy.deepcopy(weight_mask).cpu().numpy(), copy.deepcopy(bias_mask).cpu().numpy()))

    new_stable_units = [stable_indices[0]]
    for i, (source_stable, target_stable) in enumerate(zip(stable_indices[:-1], stable_indices[1:])):
        source_stable, target_stable = np.array(source_stable, dtype=np.int32), np.array(target_stable, dtype=np.int32)
        dead_stable_units = []
        for tgt in target_stable:
            if np.sum(np.abs(weight[i][0][tgt, source_stable])) == 0:
                dead_stable_units.append(tgt)
        if len(dead_stable_units) != 0:
            updated_stable_indices = list(target_stable)
            for dead_stable in dead_stable_units:
                updated_stable_indices.remove(dead_stable)
            new_stable_units.append(updated_stable_indices)
        else:
            new_stable_units.append(list(target_stable))
    return new_stable_units

#Get list of weights
def list_of_weights(network):
    weights = []
    for module in network.modules():
        if isinstance(module, nn.Linear) or isinstance(module, nn.Conv2d):
            weights.append((module.weight.cpu().detach().numpy(), module.bias.cpu().detach().numpy()))
    return weights

#Compute total activation of layers
def compute_total_activation(network, train_loader, dev, current_classes = None, binary = False):
    total_activations = []
    network.train()
    with torch.no_grad():
        for batch_idx, (data, target) in enumerate(train_loader):
            _, activations = network.forward_activations(data, current_classes)
            batch_sum_activation = [torch.sum(activation, axis = (0, 2, 3)) if len(activation.shape) != 2 else  torch.sum(activation, axis = 0) for activation in activations]

            if len(total_activations) == 0:
                total_activations = batch_sum_activation
            else:
                total_activations = [total_activations[i]+activation for i, activation in enumerate(batch_sum_activation)]

    return [total_activation.detach().cpu().numpy() for total_activation in total_activations], list_of_weights(network)

#Compute total average activation of layers (this is effectively same with above, only difference is normalization)
def compute_average_activation(network, train_loader, dev, current_classes = None, binary = False):
    total_activations = []
    network.train()
    with torch.no_grad():
        for batch_idx, (data, target) in enumerate(train_loader):
            _, activations = network.forward_activations(data, current_classes)
            batch_sum_activation = [torch.sum(activation, axis = (0, 2, 3)) if len(activation.shape) != 2 else  torch.sum(activation, axis = 0) for activation in activations]

            if len(total_activations) == 0:
                total_activations = batch_sum_activation
            else:
                total_activations = [total_activations[i]+activation for i, activation in enumerate(batch_sum_activation)]

    average_activations = [total_activation/len(train_loader.dataset) for total_activation in total_activations]
    return [average_activation.detach().cpu().numpy() for average_activation in average_activations], list_of_weights(network)

# Pick most active units 
def pick_top_neurons(activations, percentage):
    total = sum(activations)
    accumulate = 0
    indices = []
    sort_indices = np.argsort(-activations)
    for index in sort_indices:
       accumulate += activations[index]
       indices.append(index)
       if accumulate >= total * percentage / 100:
           break
    return indices

#Find the stable units that satisfies p criterion
def compute_stable_neurons(activations, in_channels, stable_outputs, activation_perc, model_type): 
    stable_indices = []

    for layer_activation in activations[0 if model_type == "conv" or model_type == "conv2"  else 1:-1]:
        stable_indices.append(pick_top_neurons(layer_activation, activation_perc))
    return [list(range(in_channels))] + stable_indices + [stable_outputs]

#Compute which connections to freeze and drop
def compute_freeze_and_drop(stable_indices, model):
    weight = []
    for module in model.modules():
        if isinstance(module, torch.nn.Linear) or isinstance(module, nn.Conv2d):
            weight_mask, bias_mask = module.get_mask()
            weight.append((copy.deepcopy(weight_mask).cpu().numpy(), copy.deepcopy(bias_mask).cpu().numpy()))

    #Create Freeze Masks        
    freeze_masks = []
    for i, (source_stable, target_stable) in enumerate(zip(stable_indices[:-1], stable_indices[1:])):
        source_stable, target_stable = np.array(source_stable, dtype=np.int32), np.array(target_stable, dtype=np.int32)
        mask_w = np.zeros(weight[i][0].shape)
        #Conv2Conv
        if len(weight[i][0].shape) == 4:
            for src_unit_stable in source_stable:
               mask_w[target_stable, src_unit_stable, :, :] = np.ones((weight[i][0].shape[2], weight[i][0].shape[3]))
        #Conv2Linear or Linear2Linear
        else:
            #Conv2Linear
            if len(weight[i-1][0].shape) == 4:
                for src_unit_stable in source_stable:

                    mask_w[target_stable, src_unit_stable*model.conv2lin_kernel_size:(src_unit_stable + 1)*model.conv2lin_kernel_size] = 1 
            #Linear2Linear
            else:
                for src_unit_stable in source_stable:
                    mask_w[target_stable, src_unit_stable] = 1 
        mask_b = np.zeros(weight[i][1].shape)
        mask_b[target_stable] = 1
        freeze_masks.append((mask_w, mask_b))

    #Create Drop Masks
    drop_masks = []
    for i, (mask_w, mask_b) in enumerate(freeze_masks):
        mask_w_drop = np.zeros(weight[i][0].shape)
        #Conv2Conv
        if len(weight[i][0].shape) == 4:
            for unit_index, b in enumerate(mask_b):
                if b:
                    mask_w_drop[unit_index, :, :, :] = np.logical_not(mask_w[unit_index])

        #Conv2Linear or Linear2Linear
        else:
            mask_w_drop = np.zeros(weight[i][0].shape)
            for unit_index, b in enumerate(mask_b):
                if b:
                    mask_w_drop[unit_index, :] = np.logical_not(mask_w[unit_index, :])
        drop_masks.append((mask_w_drop, []))
    return freeze_masks, drop_masks

# Calculate the sparsity of the model
def compute_weight_sparsity(model):
    parameters = 0
    ones = 0
    for module in model.modules():
        if isinstance(module, nn.Linear) or isinstance(module, nn.Conv2d):
            shape = module.weight.data.shape
            parameters += torch.prod(torch.tensor(shape))
            w_mask, _ = copy.deepcopy(module.get_mask())
            ones += torch.count_nonzero(w_mask)
    return float((parameters - ones) / parameters) * 100

# Drop connections plastic -> stable
def drop_connections(model, drop_masks, device):
    #Drop connections
    mask_index = 0
    num_drops = []
    for module in model.modules():
        if isinstance(module, torch.nn.Linear) or isinstance(module, nn.Conv2d):
            weight_mask, bias_mask = module.get_mask()
            before = torch.sum(weight_mask)
            weight_mask[torch.tensor(drop_masks[mask_index][0], dtype= bool)] = 0 
            after = torch.sum(weight_mask)
            num_drops.append(int(before - after))
            module.set_mask(weight_mask, bias_mask)
            mask_index += 1
    return model, num_drops
from torch.utils.data import DataLoader
from .training import test
from .utils import list_of_weights, taskset2GPUdataset

#Write a summary of the state after each task
def task_summary_log(model, loss, acc_after_drop, current_classes, args, task_id, scenario_test, stable_units_set):
    weights = list_of_weights(model)
    units = [w.shape[0] for w, _ in weights] 
    if stable_units_set is None:
        frozen_units = [0]
    else:
       frozen_units = [len(s) for s in stable_units_set[1:]]

    task_test_current = scenario_test[task_id] 
    test_loader = DataLoader(taskset2GPUdataset(task_test_current),
                             batch_size= args.batch_size*2,
                             shuffle=False)

    #Backward Tasks Accuracy
    backward_accs = []
    backward_tasks = []
    if task_id == 0:
        backward_accs.append(None)
    else:
        for backward_task_id in range(task_id):
            backward_task_dataset = scenario_test[backward_task_id]
            backward_tasks.append(backward_task_dataset.get_classes())
            test_loader = DataLoader(taskset2GPUdataset(backward_task_dataset),
                                     batch_size= args.batch_size*2,
                                     shuffle=False)
            _, acc1_back, _ = test(model, loss, test_loader,
                                   current_classes = backward_task_dataset.get_classes() if args.multihead else None)
            backward_accs.append(acc1_back)

    with open("./logs/" + args.experiment_name + "_TASK_ID_{}".format(task_id + 1) + '.txt', "w") as fout:
        fout.write(str(args))

        if task_id != 0:
            fout.write("\n" + "Top 1 Test Accuracy (Cumulative: ): "+ str(sum(backward_accs + [acc_after_drop]) / len(backward_accs + [acc_after_drop])))

        fout.write("\n" + "Top 1 Test Accuracy (Current Task After FineTuning: {}): ".format(current_classes) + str(acc_after_drop))


        count = 1
        for task, backward_acc in zip(backward_tasks, backward_accs):
            if backward_acc is None:
                continue
            fout.write("\n" + "TASK ID {}  Top 1 Test Accuracy (Backward Task {}: {}): ".format(task_id, count, task) + str(backward_acc))
            count += 1
        if args.experiment_note != "":
            fout.write("\n" + args.experiment_note)
        fout.write('\n #Units: ' +  str(units))
        fout.write('\n #Stable Units' + str(frozen_units))  


